INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resonant Blade', 'Resonant Blade is a 2d sci-fi action adventure set in a dystopian world where sound is your greatest weapon. Battle the Dark Synths across a shattered planet using the power of Resonant Tones. Manipulate sound to solve puzzles, unleash devastating Triad abilities, and shape your own combat rhythm with customizable mods. With pixel art and fast paced gameplay, Resonant Blade challenges you to listen, adapt, and strike in harmony.' FROM games WHERE igdb_id = 140792 ON CONFLICT (game_id, language_code) DO NOTHING;
