INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exovore', 'EXOVORE is a dual-stick space horror shoot’em-up inspired by the legendary Sinistar. Mine asteroids for energy, forge powerful weapons and battle through swarms of biomechanical nightmares as a colossal alien intelligence awakens to destroy you. It starts out nice and slow, giving you a chance to learn the controls and upgrade your ship. But the action and complexity builds with each level.' FROM games WHERE igdb_id = 384221 ON CONFLICT (game_id, language_code) DO NOTHING;
