INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Techno Banter', 'Surrounded by bright neons, filthy streets and even filthier techno beats, it is you who guard the entrance to the rave. Sharpen your wits and deliver lyrical smackdowns to those not worthy of partying. But beware - the stakes may or may not involve blowing up the city.' FROM games WHERE igdb_id = 250795 ON CONFLICT (game_id, language_code) DO NOTHING;
