INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You See a Monster Smoking in the Parking Lot', 'A horror-dramedy text adventure that ends in just one or two actions, but has 33 unique endings to discover. Some conclusions are dreadful and uncomfortable. Others somber. A few are just plain absurd. You set the tone. Investigate the smoking monster or kill it, think about your life, buy food, laugh or cry, drive away - and many options in between.' FROM games WHERE igdb_id = 377666 ON CONFLICT (game_id, language_code) DO NOTHING;
