INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Temporal Gunslinger', 'An action game where you play as a supernatural gunslinger. You have the power to redirect bullets mid-flight and rewind time to take down multiple foes in the blink of an eye. Travel across different time periods and slay the Reaper''s traitorous Heralds.' FROM games WHERE igdb_id = 338308 ON CONFLICT (game_id, language_code) DO NOTHING;
