INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Of Ash and Steel', 'Of Ash and Steel is an immersive third-person open-world RPG created by a passionate team that values the essence of classic old-school RPGs and modern designs. Explore the lands of a once-prosperous island, hone your combat skills, and survive in the unforgiving realm of the Kingdom of the Seven.' FROM games WHERE igdb_id = 322389 ON CONFLICT (game_id, language_code) DO NOTHING;
