INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '100 Christmas Hidden Cats', 'Celebrate the holiday season with 100 Christmas Hidden Cats, a cozy and charming hidden object adventure! Search through beautifully decorated rooms, snowy landscapes, and festive scenes to find adorable hidden cats. Each discovery brings joy and adds to your Christmas spirit. Relax, explore, and enjoy the heartwarming art and music as you uncover all the hidden kitties. Can you find all 100 cats and make this Christmas truly magical?' FROM games WHERE igdb_id = 378185 ON CONFLICT (game_id, language_code) DO NOTHING;
