INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('breaking-bricks--1', 333680, '2025-02-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9gs3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3c1p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breaking Bricks', 'Get ready to experience the thrill of BREAKING BRICKS, an addictive arcade game that will captivate players of all ages. With 40 challenging levels, you’ll have a blast breaking bricks and progressing to new stages. The goal of BREAKING BRICKS is simple: use your skill and quick reflexes to destroy all the blocks on the screen. But it won’t be as easy as it sounds! As you advance through the levels, the blocks become tougher, requiring smart strategies to overcome each challenge. What truly sets BREAKING BRICKS apart are the exciting power-ups you’ll discover throughout the game. These power-ups range from extra balls to multiply your score, to powerful weapons that destroy multiple blocks at once. Each power-up adds an extra layer of excitement and strategy, keeping you on your toes and eager for more. With its fast-paced action and intuitive controls, BREAKING BRICKS delivers an engaging experience from start to finish. Every level provides a sense of achievement as you progress.' FROM games WHERE igdb_id = 333680 ON CONFLICT (game_id, language_code) DO NOTHING;
