INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galactic Simulator2: Stargate', 'Galactic Simulator 2: Stargate is a roguelite simulation game inspired by the Fermi Paradox and the Great Filter. Pilot your ship, gather resources, build stargates, and discover other civilizations as you explore an ever-evolving galaxy.' FROM games WHERE igdb_id = 344539 ON CONFLICT (game_id, language_code) DO NOTHING;
