INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cat and Shadow and Death''s Four Friends', 'Cat and Shadow and Death''s Four Friends is a two-player platformer game. It consists of 4 chapters and 16 levels. Players need to take on the roles of Cat and Shadow respectively, use various skills and in-map mechanics to cooperate in collecting items, and reach the end together.' FROM games WHERE igdb_id = 374070 ON CONFLICT (game_id, language_code) DO NOTHING;
