INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starship Scarwolf', 'Starship Scarwolf is a 2D top-down omnidirectional shooter. As I''m a fan of vector scan games, I aimed to create an expression using only wireframe rendering. However, I couldn''t achieve this with just dots and lines, so I also used fill and circle drawing functions.' FROM games WHERE igdb_id = 371933 ON CONFLICT (game_id, language_code) DO NOTHING;
