INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahadesora', 'In this fate-tangled turn-based RPG, you play as Kunzai — a lost hero drowning in destiny. Team up with your destined partner and eccentric allies to explore a world of sand and sea, uncover the meaning of “Kun-life,” face snarky teammates, and try not to get emotionally wrecked by your own drama.' FROM games WHERE igdb_id = 379751 ON CONFLICT (game_id, language_code) DO NOTHING;
