INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gnomophobia', 'Gnomophobia is an unsettling escape-horror game where gnomes stalk you through a themed forest, staying frozen only while you’re watching them. Follow the chain of visual clues hidden in notes, outsmart the gnomes’ relentless pursuit, and find the way out of the forest!' FROM games WHERE igdb_id = 381068 ON CONFLICT (game_id, language_code) DO NOTHING;
