INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pepper Odyssey', 'Pepper Odyssey is an RPG about surviving a shipwreck in an unruly outlandish island. Survive the lawless island: fight, trade and explore. Gather scrap to trade, improve your shelter and build yourself the means to escape; or meddle in the affairs of the island and realize a vision for its future.' FROM games WHERE igdb_id = 349201 ON CONFLICT (game_id, language_code) DO NOTHING;
