INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape Observation', '‘Escape Observation’ is a short walking simulator inspired by the game ‘The Exit 8’, where you can only move your character and control your vision. It is important to note that the game is not about finding out if a room has changed, but rather that each room is different and you must be aware of the signals that these changes give you.' FROM games WHERE igdb_id = 333182 ON CONFLICT (game_id, language_code) DO NOTHING;
