INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Night Gym', 'The Night Gym is a small retro-style indie horror experience with a VHS aesthetic where a late-night workout turns into a nightmare. You arrive at the gym after hours — just you and the machines. But something feels off. The lights flicker. The silence is heavy. You''re not alone...' FROM games WHERE igdb_id = 366333 ON CONFLICT (game_id, language_code) DO NOTHING;
