INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beyond-the-illusions', 387324, '2025-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobdc2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11hv3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beyond the Illusions', 'Alright, you absolute legends—or degenerates, depending on the day—welcome to Beyond the Illusions, a 10-minute shitshow where one dude’s birthday goes from “my ex dumped me” to “am I tripping balls or is that lava?” I’m dVlpr, the sleep-deprived lunatic who puked this mess into existence over 55 hours of caffeine and regret, then “remastered” it with 25 more hours of “why the hell am I doing this?” No fancy GITIA VI budget here—just glitchy vibes, broken dreams, and a big ol’ “screw polish” attitude.
