INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drop The Cat', 'This is the ultimate casual puzzle game that perfectly blends bright and colorful cat visuals, addictive block puzzle mechanics, and smart logic puzzle challenges. This easy puzzle game is designed to be both a relaxing, healing game and a stimulating brain game. If you love match puzzles or want a great puzzle you can enjoy anytime, this is the perfect choice.' FROM games WHERE igdb_id = 387473 ON CONFLICT (game_id, language_code) DO NOTHING;
