INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paper Mages', 'A CCG / Deckbuilder / RTS / Third Person Platformer. Take part in the Pentad Mage Duels, where you and other apprentices control paper avatars to duel in a paper castle and become mages. With a deck of 130 cards that combine in different ways, use real-time systemic strategy to win.' FROM games WHERE igdb_id = 190775 ON CONFLICT (game_id, language_code) DO NOTHING;
