INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chase: Police Rush', 'The Chase is an endless driving game where you take the role of a driver on the run from the police. Set on an open, continuous maps, the objective is simple: stay ahead of the cops for as long as possible while avoiding obstacles and collecting essential items like fuel, magnets, coins and presents. With high-speed chases, explosive crashes, and unlockable vehicles and environments, The Chase delivers a heart-pounding experience.' FROM games WHERE igdb_id = 364815 ON CONFLICT (game_id, language_code) DO NOTHING;
