INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cardboard Fighter', 'Cardboard Fighter is an immersive VR action-adventure designed for Google Cardboard and mobile VR platforms. Developed by Hoglig, the game features a story-driven experience where players must defend a city against waves of monsters. Experience intense first-person combat and intuitive VR shooting mechanics optimized for mobile platforms, offering a 360-degree battle experience as you fight to survive and progress through the story.' FROM games WHERE igdb_id = 395370 ON CONFLICT (game_id, language_code) DO NOTHING;
