INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mart Mayhem', 'Be a convenience-store clerk in a first-of-its-kind chat game—and kick out AI Karens. There are no preset choices. Say what you couldn’t in real life and enjoy how the AI responds differently each time. A stress-relief game where your what-ifs come to life!' FROM games WHERE igdb_id = 373438 ON CONFLICT (game_id, language_code) DO NOTHING;
