INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Margaret''s Sin', 'Margaret is a pious, humble woman who’s been left alone after a brief marriage. She’s had rules hammered into her for too long to easily discard her inhibitions and preconceptions, but deep inside, she’s very curious about a world she’s never explored before — the world of orgasms and good sex.' FROM games WHERE igdb_id = 332149 ON CONFLICT (game_id, language_code) DO NOTHING;
