INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Witch Stories', 'First-person retro horror RPG. Non-linear, open world, branching dialog, voice acted, simple controls, and tons of easter eggs to discover. Set in the 1700s. You are a woman living in a cottage in the forest with your husband and newborn baby. Your story unfolds over two days, whether you choose to act or not.' FROM games WHERE igdb_id = 329681 ON CONFLICT (game_id, language_code) DO NOTHING;
