INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Creeping Clark', '"Creeping Clark" is a linear indie horror game that pulls players into Sophie Clark''s unsettling experience in a remote forest house. With a playtime of ~60 minutes (Demo: ~25 minutes), follow Sophie as she navigates a series of disturbing events that blur the line between anxiety and reality.' FROM games WHERE igdb_id = 336169 ON CONFLICT (game_id, language_code) DO NOTHING;
